    "× α ＋ β ＞ 1 は「規模に関して収穫逓増（規模の経済）」であり、規模拡大に伴い単位あたりコストは「低下」します。",
    "× 0 ＜ β ＜ 1 であるため、単一要素の投入増加に対しては「限界生産力逓減の法則（dY/dLは逓減）」が成り立ちます。"
