    "バターとマーガリンのように、一方が値上がりすると他方の需要が増える関係にある財同士は「代替財」であり、需要の交差価格弾力性は正（プラス）となる。",
    "コーヒーと砂糖のように、一緒に消費される関係にある財同士は「代替財」であり、需要の交差価格弾力性は負（マイナス）となる。",
