    "○ 正しい！代替関係にある財は、ライバルの価格が上がると自社の需要が増えるため、交差価格弾力性は正（e_xy ＞ 0）になります。",
    "× 一緒に消費される関係（コーヒーと砂糖、自動車とガソリン等）は「補完財」であり、片方が値上がりすると両方買い控えられるため交差弾力性は「負（e_xy ＜ 0）」です。",
