    "○ 正しい！CPIはラスパイレス指数であるため、価格高騰した財を買い控える代替行動を反映できず、インフレ率を「高め（上方バイアス）」に算出する傾向があります。",
    "× GDPデフレーターは「パーシェ算式（名目GDP ÷ 実質GDP）」で計算されます。",
